// <diletta-data-header-row> — a INSTÂNCIA WEB de `design-system-data-header-row`.
//
// É a FONTE ÚNICA da grade: largura e alinhamento de cada coluna saem daqui, e
// DilettaDataRow consome a mesma declaração. Sem uma fonte só, cabeçalho e corpo
// divergem e a tabela mente sobre qual coluna é qual.
import './diletta-data-column-header.js';

const PORTE = { regular: 40, compacto: 36 };

class DilettaDataHeaderRow extends HTMLElement {
  static observedAttributes = ['porte', 'selecao', 'colunas'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  /// `Nome:1fr | CPF:145 | Data:145:fim` — rótulo, largura, alinhamento opcional.
  get colunas() {
    return (this.getAttribute('colunas') || '')
      .split('|').map((s) => s.trim()).filter(Boolean)
      .map((s) => {
        const [rotulo, largura = '1fr', alinhamento = 'inicio'] = s.split(':').map((x) => x.trim());
        return { rotulo, largura: /^\d+$/.test(largura) ? `${largura}px` : largura, alinhamento };
      });
  }

  /// A GRADE que a linha de dados tem que consumir. É o contrato entre as duas.
  get grade() {
    return this.colunas.map((c) => c.largura).join(' ');
  }

  render() {
    const porte = PORTE[this.getAttribute('porte')] ? this.getAttribute('porte') : 'regular';
    const porteCelula = porte === 'compacto' ? 'compacto' : 'regular';
    const cabecas = this.colunas.map((c) =>
      `<diletta-data-column-header rotulo="${c.rotulo.replace(/"/g, '&quot;')}"
         porte="${porteCelula}" alinhamento="${c.alinhamento}"></diletta-data-column-header>`).join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .cabecalho {
          box-sizing: border-box;
          height: ${PORTE[porte]}px;
          display: grid; grid-template-columns: ${this.grade}; gap: 16px; align-items: center;
          padding: 0 16px;
          /* Sem preenchimento, sem régua e sem tarja. Medido no pixel: os 36px do
             cabeçalho são brancos e os 16 seguintes são o fundo da TELA — não há
             linha nenhuma. O que separa é o respiro de 16 e o traço externo da
             primeira linha, e foi esse traço que eu confundi com uma régua. */
          background: transparent;
        }
      </style>
      <div class="cabecalho" part="cabecalho" role="row">${cabecas}</div>`;
  }
}

customElements.define('diletta-data-header-row', DilettaDataHeaderRow);
export { DilettaDataHeaderRow, PORTE };
